-- Study Abroad country content, BATCH 5: Japan, South Korea, China, Turkey, Portugal.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('japan', 'south-korea', 'china', 'turkey', 'portugal'));
UPDATE countries SET why_title = 'Why study in Japan?', why_body = '<p>Japan combines world-class research, advanced technology and a safe, orderly society. Its universities are strong in engineering, robotics, natural sciences and design, and a growing number of degrees are taught in English.</p><ul><li>Leading research universities such as the University of Tokyo and Kyoto University</li><li>Strong industry links in manufacturing, electronics, automotive and robotics</li><li>English-taught degree programmes at many top universities</li><li>Graduates may stay on a job-hunting visa after study</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students need a <strong>Student visa</strong>. Your institution first applies for a <strong>Certificate of Eligibility (CoE)</strong> from the Immigration Services Agency, and you then apply for the visa at a Japanese embassy or consulate.</p><ul><li>Admission letter and Certificate of Eligibility (CoE) obtained through the university</li><li>Proof of funds: reported at about ¥2,000,000 a year, or a scholarship letter such as MEXT</li><li>Passport, photo, visa application form and academic records</li><li>Visa fee: reported at about ¥3,000 for a single entry (April 2026 to March 2027)</li><li>Residence card issued on arrival</li><li>Work: students may work part time with a permission for activity outside the status of residence (usually up to 28 hours a week)</li><li>After graduation: a job-hunting period may be allowed on a Designated Activities status</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Immigration Services Agency of Japan site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply to each university directly. Many English-taught programmes have separate international admissions tracks and early deadlines.</p><ul><li>Academic transcripts and certificates</li><li>English or Japanese language proof</li><li>Statement of purpose and research plan for graduate applicants</li><li>Letters of recommendation</li><li>EJU (Examination for Japanese University Admission) scores for some Japanese-taught undergraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition at national and public universities is set by the government and is lower than at private universities. Private universities and graduate schools often cost more.</p><ul><li>National universities: about ¥540,000 a year in tuition plus an entrance fee of about ¥280,000 (standard figures; check each university)</li><li>Private universities: roughly ¥800,000-¥1,500,000+ a year, more for medicine and science</li><li>Living costs: about ¥100,000-¥150,000 a month; Tokyo is the most expensive</li><li>National Health Insurance enrolment is required (monthly premium is small for students)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements differ by university and level.</p><ul><li><strong>Bachelor''s:</strong> 12 years of school education; students from 11-year systems may need a foundation year</li><li><strong>Master''s:</strong> a relevant bachelor''s degree; many programmes ask for a research plan and a supervisor''s agreement</li><li><strong>English:</strong> IELTS 6.0-6.5 or TOEFL 80-100 for English-taught programmes</li><li><strong>Japanese:</strong> JLPT N1 or N2 for Japanese-taught programmes</li></ul>' WHERE slug = 'japan';
UPDATE countries SET why_title = 'Why study in South Korea?', why_body = '<p>South Korea combines advanced technology, strong research universities and a rich popular culture. Many universities offer English-taught programmes, and the government supports international students through the Global Korea Scholarship.</p><ul><li>Strong in electronics, computing, engineering, business and media</li><li>Government and university scholarships for international students</li><li>Growing number of English-taught degrees</li><li>Graduates may apply for a job-seeking visa</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students need a <strong>D-2 student visa</strong> for degree study (D-4 for language courses). Your university issues the admission documents, and you apply at the Korean embassy or consulate.</p><ul><li>Admission letter and Certificate of Admission from the university</li><li>Proof of funds: often about ₩20 million (around USD 15,000), but the requirement is set by each university. A 2026 proposal would waive it for students with TOPIK 4 or above, so check whether it is in force</li><li>Bank balance certificate in your name, passport and academic records</li><li>Check that your university is allowed to issue student visas: 20 universities were restricted from fall 2026</li><li>Work: students may work part time with permission, with hours depending on language level</li><li>After graduation: a job-seeking visa (D-10) is available for eligible graduates</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Korea Immigration Service and Study in Korea site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply to each university''s international admissions portal. Deadlines are usually in the months before the March and September semesters.</p><ul><li>Academic transcripts and certificates, often apostilled or notarised</li><li>Language proof (TOEFL, IELTS or TOPIK)</li><li>Statement of purpose and study plan</li><li>Letters of recommendation</li><li>Portfolio or interview for some programmes</li><li>Passport copy and application fee</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition is lower than in the US or UK but varies by university and subject. Engineering and medicine cost more than humanities.</p><ul><li>Tuition: roughly ₩6-14 million a year at many private universities (estimate; national universities are lower)</li><li>Living costs: about ₩900,000-₩1,500,000 a month; Seoul is more expensive</li><li>Dormitory fees are lower than private housing</li><li>National Health Insurance enrolment is required for long-stay students</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> 12 years of school education with strong results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree and often a study plan</li><li><strong>English:</strong> TOEFL 80-100 or IELTS 6.0-7.0 for English-taught courses</li><li><strong>Korean:</strong> TOPIK level 3-4 or higher for Korean-taught courses</li></ul>' WHERE slug = 'south-korea';
UPDATE countries SET why_title = 'Why study in China?', why_body = '<p>China has some of the world''s fastest-rising universities, large research budgets and lower tuition than most Western countries. In the QS World University Rankings 2027, Peking University is 13th and Tsinghua University 14th.</p><ul><li>Strong in engineering, computing, medicine and business</li><li>Large scholarship programmes for international students</li><li>English-taught degrees at leading universities</li><li>A major hub for technology and manufacturing</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Students on programmes longer than 180 days need an <strong>X1 visa</strong> (X2 for shorter programmes). After arrival you convert it to a student residence permit.</p><ul><li>Admission notice from a Chinese university</li><li>Visa Application for Study in China form (JW201 or JW202)</li><li>Passport with enough validity (at least 6 months) and a completed application form with photo</li><li>Physical examination record for stays over 6 months</li><li>Within 30 days of arrival: apply for a student residence permit at the local Public Security Bureau</li><li>CSC scholarship holders use the scholarship letter as proof of funds, and receive a JW201 form</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Chinese embassy or visa centre site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university''s international admissions office or through the national scholarship platform.</p><ul><li>Academic transcripts and certificates, notarised where required</li><li>Language proof (HSK for Chinese-taught, IELTS or TOEFL for English-taught)</li><li>Study plan or personal statement</li><li>Two recommendation letters for graduate programmes</li><li>Passport copy and photographs</li><li>Physical examination record and a non-criminal record certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>China has no single national tuition fee; costs depend on the university and subject. Tuition is generally lower than in Western countries.</p><ul><li>Tuition: roughly US$2,000-$23,000 a year (reported range, depending on the university and course)</li><li>Living costs: about RMB 3,000-6,000 a month depending on the city; Beijing and Shanghai cost more</li><li>Dormitories are cheaper than private housing</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school with good grades</li><li><strong>Master''s:</strong> a relevant bachelor''s degree, often with a study plan</li><li><strong>PhD:</strong> a master''s degree and a research proposal</li><li><strong>Language:</strong> HSK 4-5 for Chinese-taught programmes; IELTS 6.0-6.5 or TOEFL 80-90 for English-taught programmes</li><li>Applicants must be in good health and have no criminal record</li></ul>' WHERE slug = 'china';
UPDATE countries SET why_title = 'Why study in Turkey?', why_body = '<p>Turkey offers a wide range of state and private universities at lower costs than many European countries, with growing English-taught programmes. It sits between Europe and Asia and has a rich culture.</p><ul><li>Lower tuition and living costs than most European destinations</li><li>English-taught programmes in engineering, medicine, business and architecture</li><li>Generous government scholarships through Türkiye Bursları</li><li>Strong Turkish language and cultural experience</li></ul>', visa_title = 'Student visa and residence permit', visa_body = '<p>Students normally enter Turkey with a <strong>student entry visa</strong> (or visa-free where allowed) and then apply for a <strong>student residence permit</strong> after arrival. Applications made from abroad are not valid.</p><ul><li>Acceptance letter or student certificate from a Turkish university</li><li>Apply for the residence permit within the first month after arrival</li><li>Residence card fee: reported at 964 TL for 2026 (check the current amount)</li><li>Health insurance valid in Turkey</li><li>Passport valid for at least 60 days beyond the permit period (reported)</li><li>Work: a student permit does not allow work; a separate work permit is needed</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Directorate General of Migration Management site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Most universities take international applications through their own portal. Some use national exams or the SAT, and others use their own entrance tests (YÖS).</p><ul><li>Academic transcripts and certificates</li><li>Language proof (English or Turkish)</li><li>SAT, YÖS or university entrance exam results, where required</li><li>Motivation letter or portfolio for some programmes</li><li>Passport copy and photographs</li><li>Equivalence of school certificates where requested</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>State universities charge lower fees than private foundation universities. Costs depend on the university and city.</p><ul><li>Tuition: state universities are usually the lowest; private universities roughly US$5,000-$20,000 a year (estimate; medicine costs more)</li><li>Living costs: about US$400-$800 a month depending on the city; Istanbul is more expensive</li><li>Residence permit card: reported at about 964 TL</li><li>Health insurance is required for students</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a high school diploma; many universities ask for SAT, YÖS or national exam results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree and, at some universities, ALES or GRE</li><li><strong>English:</strong> IELTS 5.5-6.5 or TOEFL 70-90 for English-taught programmes</li><li><strong>Turkish:</strong> TÖMER C1 for Turkish-taught programmes</li></ul>' WHERE slug = 'turkey';
UPDATE countries SET why_title = 'Why study in Portugal?', why_body = '<p>Portugal offers a high quality of life, a pleasant climate and lower costs than most of Western Europe, with a growing number of English-taught programmes in Lisbon, Porto and other cities.</p><ul><li>Lower tuition and living costs than many European countries</li><li>English-taught Master''s and some Bachelor''s programmes</li><li>Growing technology, startup and tourism sectors</li><li>Safe, welcoming country with a large international student community</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students apply for a <strong>national long-stay student visa (type D)</strong> at the Portuguese consulate, then convert it to a <strong>residence permit</strong> through AIMA after arrival.</p><ul><li>Admission letter or proof of enrolment from a Portuguese institution</li><li>Proof of funds: reported at about €760-€870 a month, tied to the national minimum wage (check the consulate)</li><li>Accommodation proof and health insurance</li><li>Criminal record certificate and passport; a Portuguese tax number (NIF) is also useful</li><li>Fees: visa reported at about €110 and residence permit about €170</li><li>Processing: visa often takes 30-90 days; AIMA appointments after arrival can take months</li><li>Work: students may work part time within the permitted limits</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Portuguese consulate and AIMA site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>International students apply directly to each university, often through a dedicated international student application with several phases.</p><ul><li>Academic transcripts and certificates, with translations and apostilles where needed</li><li>English or Portuguese language proof</li><li>Motivation letter and CV for Master''s programmes</li><li>Entrance exams or portfolio for some courses</li><li>Passport copy</li><li>Application fee at some universities</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public universities charge non-EU students higher fees than EU students, but fees are low compared with many other destinations. Private universities charge more.</p><ul><li>Public university tuition (non-EU): often about €3,000-€7,000 a year (reported)</li><li>Private universities: roughly €5,000-€15,000+ a year</li><li>Living costs: about €700-€1,200 a month; Lisbon is the most expensive</li><li>Health insurance is required for the visa</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the institution and level.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school; some courses need specific subjects or an entrance exam</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof (IELTS 6.0 or equivalent) for English-taught courses; Portuguese (CAPLE) for Portuguese-taught courses</li><li>Applicants must usually be at least 18</li></ul>' WHERE slug = 'portugal';
COMMIT;
